<?php
namespace App\Libraries\Platform;

/** Annual service purchases use PlatformBilling, never physical checkout. */
class AnnualWebsitePackage
{
    public const SKU='PACKET-990-ANNUAL';
    public static function matches(array $product): bool { return ($product['sku']??'')===self::SKU; }
    public static function add(Store $s): int
    {
        return $s->transaction(function() use($s){
            $existing=$s->one('SELECT id FROM products WHERE sku=?',[self::SKU]);
            if($existing){return (int)$existing['id'];}
            return $s->insert('products',[
                'sku'=>self::SKU,'name'=>'แพ็กเกจเว็บไซต์อัจฉริยะ SKYNEXT INTER · 990 บาท/ปี',
                'category'=>'บริการเว็บไซต์รายปี','image'=>'platform/assets/skynext-smart-website-990.png',
                'price_satang'=>Membership::ANNUAL_SATANG,'stock'=>0,'pv'=>0,'active'=>1,'inquiry_only'=>1,
                'short_description'=>'แพ็กเกจเว็บไซต์อัจฉริยะ SKYNEXT INTER เปิดรับผู้สมัครจากสายงานอื่น สำหรับใช้เป็นช่องทางนำเสนอสินค้าและบริการออนไลน์ ค่าใช้บริการเพียง 990 บาทต่อปี ตามขอบเขตและเงื่อนไขแพ็กเกจ',
                'inquiry_label'=>'สอบถามรายละเอียดแพ็กเกจ','created_at'=>Store::now(),
                'description'=>"ต่างสายงาน ก็สมัครใช้บริการได้\nสมัครใช้เว็บไซต์อัจฉริยะ SKYNEXT INTER เพื่อเป็นช่องทางนำเสนอข้อมูลสินค้าและบริการออนไลน์ เปิดรับผู้สนใจจากสายงานอื่นที่ต้องการใช้งานเว็บไซต์ภายใต้รูปแบบและเงื่อนไขของแพลตฟอร์ม\n\nรายละเอียดแพ็กเกจ\nชื่อแพ็กเกจ: SKYNEXT INTER Smart Website\nประเภทสินค้า: บริการเว็บไซต์อัจฉริยะรายปี\nกลุ่มผู้สมัคร: ผู้สนใจจากสายงานอื่นที่ต้องการสมัครใช้เว็บไซต์\nค่าใช้บริการ: 990 บาทต่อปี\nระยะเวลาใช้บริการ: 1 ปีต่อรอบบริการ\nการต่ออายุ: ชำระค่าใช้บริการสำหรับรอบปีถัดไป\n\nจุดประสงค์การใช้งาน\n• ใช้เป็นช่องทางนำเสนอข้อมูลสินค้าและบริการ\n• รวบรวมข้อมูลสำหรับส่งให้ลูกค้าหรือผู้สนใจเข้าชม\n• ใช้ลิงก์เว็บไซต์ประกอบการแนะนำธุรกิจผ่านช่องทางออนไลน์\n• เพิ่มช่องทางให้ผู้สนใจศึกษาข้อมูลก่อนติดต่อสอบถาม\n\nขั้นตอนสมัครใช้บริการ\n1. แจ้งความประสงค์สมัครแพ็กเกจเว็บไซต์อัจฉริยะ\n2. ส่งข้อมูลผู้สมัครและข้อมูลที่จำเป็นสำหรับเปิดใช้งาน\n3. ตรวจสอบรายละเอียดบริการและเงื่อนไขการใช้งาน\n4. ชำระค่าใช้บริการรายปี 990 บาท ผ่านหน้าสิทธิ์ใช้งานและต่ออายุ Platform\n5. รับข้อมูลเข้าใช้งานตามขั้นตอนที่ผู้ให้บริการกำหนด\n\nเงื่อนไขบริการ\n• ราคา 990 บาทเป็นค่าใช้บริการเว็บไซต์ต่อปี ไม่มีค่าจัดส่งและไม่มีคะแนน PV\n• ฟีเจอร์ พื้นที่ใช้งาน และสิทธิ์จัดการเว็บไซต์เป็นไปตามขอบเขตแพ็กเกจที่แจ้งก่อนสมัคร\n• โดเมนส่วนตัว งานออกแบบเพิ่มเติม และบริการเสริม ต้องตรวจสอบว่ารวมอยู่ในแพ็กเกจหรือมีค่าใช้จ่ายเพิ่มเติม\n• ผู้สมัครต้องมีสิทธิ์ใช้ข้อมูล รูปภาพ และเนื้อหาที่นำขึ้นเว็บไซต์\n• ตรวจสอบสถานะบัญชี วันเริ่มบริการ และวันหมดอายุที่หน้าสิทธิ์ใช้งานก่อนชำระเงิน ระบบเปิดสิทธิ์หลังยืนยันยอด ผู้รับ และธุรกรรมสำเร็จ\n• สมาชิก SKYNEXT เดิมที่เลือกทดลองใช้ 30 วัน จะเปิดรายการชำระเมื่อครบกำหนดทดลองใช้"
            ]);
        });
    }
}
